from coordinator.crypto import verify_signature


def resources(body):
    return set(body['expected']) | set(body['writes'])


def authorized(envelope, grants, keys, tick):
    """True when one current grant covers the whole operation at this tick and signed it."""
    body = envelope['signed']
    for grant in grants.values():
        if grant['principal'] != body['principal'] or grant['revoked']:
            continue
        if not grant['valid_from'] <= tick <= grant['valid_to']:
            continue
        if not resources(body) <= set(grant['resources']):
            continue
        key = keys.get(grant['keyid'])
        if key is None:
            continue
        if any(signature.get('keyid') == grant['keyid'] and verify_signature(body, signature, key)
               for signature in envelope['signatures']):
            return True
    return False


def in_window(body, tick):
    window = body['window']
    return window['not_before'] <= tick <= window['not_after']

import json
from pathlib import Path

from coordinator.errors import CoordinatorError


def _read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def load_bundle(data_dir):
    """Read the release batch files without interpreting them."""
    root = Path(data_dir)
    envelopes = [json.loads(line) for line in (root / 'operations.jsonl').read_text(encoding='utf-8').splitlines() if line.strip()]
    return {
        'batch': _read(root / 'batch.json'),
        'initial': _read(root / 'initial_state.json'),
        'grants': _read(root / 'grants.json'),
        'keys': _read(root / 'keys.json'),
        'envelopes': envelopes,
    }


def _latest(records, body):
    selected = {}
    for record in records:
        current = body(record)
        selected[current['id']] = record
    return selected


def current_grants(bundle):
    return _latest(bundle['grants'], lambda grant: grant)


def current_operations(bundle):
    """Map each batch member to its current signed operation envelope."""
    available = _latest(bundle['envelopes'], lambda envelope: envelope['signed'])
    operations = {}
    for member in bundle['batch']['members']:
        if member not in available:
            raise CoordinatorError(f'operation {member} was not delivered')
        operations[member] = available[member]
    return operations

import copy


class ResourceStore:
    """In-memory copy of the resource registers used while a batch is coordinated."""

    def __init__(self, values):
        self._values = copy.deepcopy(values)

    def compare_and_set(self, expected, writes):
        """Atomically compare every expected value and apply all writes only if they all match."""
        for name in list(expected) + list(writes):
            if name not in self._values:
                raise KeyError(name)
        if any(self._values[name] != value for name, value in expected.items()):
            return False
        self._values.update(writes)
        return True

    def snapshot(self):
        return copy.deepcopy(self._values)

